 // ----- Forms
 const field=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${attrs}></label>`;
 const area_=(name,label,value='',attrs='')=>`<label>${label}<textarea name="${name}" ${attrs}>${e(value)}</textarea></label>`;
 const sel=(name,label,opts,value,attrs='')=>`<label>${label}<select name="${name}" ${attrs}>${opts.map(o=>{const [k,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(k)}" ${k===value?'selected':''}>${e(t)}</option>`;}).join('')}</select></label>`;
 const boxes=(name,list,chosen)=>`<div class="hr-boxes tr-boxes">${list.map(([k,t])=>`<label><input type="checkbox" name="${name}" value="${e(k)}" ${chosen.includes(k)?'checked':''}> ${e(t)}</label>`).join('')}</div>`;
